def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    base = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Interior rows are the repeated rows without boundary-marker colors.
    interior = [r for r in range(h) if all(x == base for x in grid[r])]
    if not interior:
        interior = [r for r in range(h) if sum(x == base for x in grid[r]) > w // 2]

    # Grid separators are columns with a constant non-base value in the interior.
    const_cols = {}
    for c in range(w):
        vals = {grid[r][c] for r in interior}
        if len(vals) == 1 and next(iter(vals)) != base:
            const_cols.setdefault(next(iter(vals)), []).append(c)
    sep = max(const_cols, key=lambda v: len(const_cols[v])) if const_cols else None
    structural_cols = const_cols.get(sep, [])

    # Colored intersections identify the horizontal and vertical lattice lines.
    def is_marker(v):
        return v != base and v != sep

    rows = [r for r in range(h) if any(is_marker(v) for v in grid[r])]
    cols = [c for c in structural_cols
            if any(is_marker(grid[r][c]) for r in range(h))]

    out = [[base for _ in range(max(0, len(cols) - 1))]
           for _ in range(max(0, len(rows) - 1))]
    for i in range(len(rows) - 1):
        for j in range(len(cols) - 1):
            corners = [grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]]]
            if corners[0] != base and corners[0] != sep and all(v == corners[0] for v in corners):
                out[i][j] = corners[0]
    return out
